    //   var[j] = sum_i (data[i][j] - mean[j])^2
    Func var("var");
    {
        RDom r_var(0, n, "r_var");
        Expr zero = cast<num_t>(Expr(0.0));

        var(j) = zero;
        Expr diff = data_param(j, r_var) - mean(j);
        var(j) += diff * diff;
    }

    // Standard deviation with epsilon handling:
    // Original C:
    //   stddev[j] = 0;
    //   for (i) stddev[j] += (data[i][j] - mean[j])^2;
    //   stddev[j] /= float_n;
    //   stddev[j] = sqrt(stddev[j]);
    //   stddev[j] = stddev[j] <= eps ? 1.0 : stddev[j];
    //
    // We compute:
    //   sigma = sqrt(var[j] / float_n);
    //   stddev[j] = (sigma <= eps) ? 1.0 : sigma;
    Func stddev("stddev");
    {
        Expr eps = cast<num_t>(Expr(0.1));  // SCALAR_VAL(0.1)
        Expr one = cast<num_t>(Expr(1.0));
        Expr sigma = sqrt(var(j) / float_n_param);
        stddev(j) = select(sigma <= eps, one, sigma);
    }

    // Center and reduce the column vectors:
    // Original C:
    //   for (i = 0; i < N; i++)
    //     for (j = 0; j < M; j++) {
    //       data[i][j] -= mean[j];
    //       data[i][j] /= sqrt(float_n) * stddev[j];
    //     }
    //
    // We'll compute a new Func `normalized(j, i)` instead of modifying data in place:
    //   normalized(j, i) = (data[i][j] - mean[j]) / (sqrt(float_n) * stddev[j])
    Func normalized("normalized");
    {
        Expr sqrt_n = sqrt(float_n_param);
        normalized(j, i) = (data_param(j, i) - mean(j)) /
                           (sqrt_n * stddev(j));
    }

    // Correlation matrix:
    // Using normalized data, the off-diagonals are dot products of
    // normalized columns. We compute:
    //
    //   corr(q,p) = sum_k normalized(q,k) * normalized(p,k);
    //   corr(p,p) = 1.0;
    //
    // Note: corr(q,p) corresponds to C corr[p][q].
    Func corr("corr");
    {
        RDom r_k(0, n, "r_k");
        Expr zero = cast<num_t>(Expr(0.0));
        Expr one  = cast<num_t>(Expr(1.0));

        // Reduction: accumulate dot products for all (q,p).
        corr(q, p) = zero;
        corr(q, p) += normalized(q, r_k) * normalized(p, r_k);

        // Final pass: explicitly set the diagonal to 1.0 to match
        // PolyBench semantics.
        corr(q, q) = one;
    }

    // ------------------------------------------------------------------
    // Scheduling
    // ------------------------------------------------------------------

    Target target = get_host_target();
    const int vec = natural_vector_size<num_t>(target);

    // Reasonable tile sizes; chosen to balance locality and parallel work.
    const int mean_tile   = 64;
    const int norm_tile_i = 64;
    const int corr_tile_q = vec * 4;   // ensure multiple of vector width
    const int corr_tile_p = 32;

    // mean: 1D over columns, reduction over rows.
    {
        Var jo("mean_jo"), ji("mean_ji");
        mean.compute_root();
        // Pure definition (zero-init).
        mean
            .split(j, jo, ji, mean_tile)
            .parallel(jo)
            .vectorize(ji, vec);
        // Reduction step: sum over rows, parallelize over columns.
        mean.update()
            .split(j, jo, ji, mean_tile)
            .parallel(jo)
            .vectorize(ji, vec);
    }

    // var: same structure as mean.
    {
        Var jo("var_jo"), ji("var_ji");
        var.compute_root();
        var
            .split(j, jo, ji, mean_tile)
            .parallel(jo)
            .vectorize(ji, vec);
        var.update()
            .split(j, jo, ji, mean_tile)
            .parallel(jo)
            .vectorize(ji, vec);
    }

    // stddev: simple per-column map.
    {
        Var jo("std_jo"), ji("std_ji");
        stddev
            .compute_root()
            .split(j, jo, ji, mean_tile)
            .parallel(jo)
            .vectorize(ji, vec);
    }

    // normalized: 2D map over (i,j). We parallelize over rows (i) and
    // vectorize over columns (j), matching memory layout
    //   normalized(j, i)  ==> j is innermost coordinate.
    {
        Var io("norm_io"), ii("norm_ii");
        normalized
            .compute_root()
            .split(i, io, ii, norm_tile_i)
            .parallel(io)
            .vectorize(j, vec);
    }

    // corr: heavy MxM reduction over k. We tile in (q,p), parallelize
    // across tiles, and vectorize across q (the innermost / x dimension).
    {
        Var qo("corr_qo"), po("corr_po");
        Var qi("corr_qi"), pi("corr_pi");
        Var tile("corr_tile");

        // Pure definition (initialization).
        corr
            .compute_root()
            .tile(q, p, qo, po, qi, pi, corr_tile_q, corr_tile_p)
            .fuse(qo, po, tile)      // single parallel dimension over tiles
            .parallel(tile)
            .vectorize(qi, vec);

        // Update 0: the reduction corr(q,p) += ...
        corr.update(0)
            .tile(q, p, qo, po, qi, pi, corr_tile_q, corr_tile_p)
            .fuse(qo, po, tile)
            .parallel(tile)
            .vectorize(qi, vec);

        // Update 1: corr(q,q) = 1;  (cheap diagonal pass)
        {
            Var q_outer("corr_diag_outer"), q_inner("corr_diag_inner");
            corr.update(1)
                .split(q, q_outer, q_inner, corr_tile_q)
                .parallel(q_outer)
                .vectorize(q_inner, vec);
        }
    }

    // Bind parameters and input buffer.
    data_param.set(data);
    float_n_param.set(float_n);

    // Build a pipeline for the final correlation Func.
    Pipeline pipeline(corr);

    // JIT compile the pipeline.
    pipeline.compile_jit(target);

    // Time only the kernel execution (not initialization).
    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel: realize corr into corr_buf.
    pipeline.realize(corr_buf);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the result, similar to gemm.cpp.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int ii = 0; ii < m; ii++) {
            for (int jj = 0; jj < m; jj++) {
                // corr_buf(jj, ii) corresponds to corr[ii][jj] in C.
                std::cerr << corr_buf(jj, ii) << '\n';
            }
        }
    }

    // Print timing (seconds).
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
