    Param<num_t> float_n_param("float_n_param");

    // Vars: i = row index (0..n-1), j = column index (0..m-1)
    //       p,q = indices for correlation matrix (0..m-1)
    Var i("i"), j("j"), p("p"), q("q");

    // -------- Statistics along columns (j) --------

    // Column-wise sum and mean:
    // Original C:
    //   mean[j] = 0;
    //   for (i = 0; i < N; i++)
    //       mean[j] += data[i][j];
    //   mean[j] /= float_n;
