    // We first accumulate a sum to avoid N*M divisions, then divide once per column:
    Func mean_sum("mean_sum");
    {
        RDom r_mean(0, n, "r_mean");
        Expr zero = cast<num_t>(Expr(0.0));
        mean_sum(j) = zero;
        mean_sum(j) += data_param(j, r_mean);
