        corr(q, p) = select(p == q, one, zero);

        // Update definition: accumulate outer products of normalized columns.
        // For diagonal entries, we leave them at 1 by making the update a no-op.
        Expr prod = normalized(q, r_k) * normalized(p, r_k);
        corr(q, p) = select(p == q,
                            corr(q, p),          // keep diagonal == 1
                            corr(q, p) + prod);  // accumulate off-diagonal
