    //
    //   normalized(k, j) =
    //       (data[k][j] - mean[j]) / (sqrt(float_n) * stddev[j])
    //
    // Layout choice:
    //   * 'sample' (k) is the first dimension -> contiguous in memory.
    //   * 'col'     is the second dimension.
    //
    // This makes the later dot-products along 'sample' memory-friendly.
    Func normalized("normalized");
    {
        Expr sqrt_n = sqrt(float_n_param);
        normalized(sample, col) =
            (data_param(col, sample) - mean(col)) /
            (sqrt_n * stddev(col));
    }

    // Correlation matrix:
    //
    // Original C (schematically, using normalized data):
    //   for (i = 0; i < M-1; i++) {
    //     corr[i][i] = 1.0;
    //     for (j = i+1; j < M; j++) {
    //       corr[i][j] = sum_k normalized[k][i] * normalized[k][j];
    //       corr[j][i] = corr[i][j];
    //     }
    //   }
    //   corr[M-1][M-1] = 1.0;
    //
    // We compute the full symmetric Gram matrix:
    //   corr_base[p,q] = sum_k normalized[k][p] * normalized[k][q]
    // and then explicitly set the diagonal to 1.0 to match the original
    // semantics (up to floating-point rounding).
    Var p("p"), q("q");
    Func corr_base("corr_base");
    {
        RDom r_k(0, n, "r_k");
        Expr zero = cast<num_t>(0.0);

        corr_base(q, p) = zero;
        corr_base(q, p) += normalized(r_k, q) * normalized(r_k, p);
    }

    Func corr("corr");
    {
        Expr one = cast<num_t>(1.0);
        // corr_buf(q, p) corresponds to C corr[p][q]
        corr(q, p) = select(p == q, one, corr_base(q, p));
    }

    // --- Scheduling -------------------------------------------------------
    //
    // The following schedule is tuned for a modern multicore CPU:
    //  * Parallelize across independent columns/rows where possible.
    //  * Vectorize along the innermost (contiguous) dimension.
    //  * Keep large intermediate results (normalized, corr_base) at root
    //    so they are computed once and reused efficiently.

    Target target = get_host_target();
    const int vec_width = target.natural_vector_size(type_of<num_t>());

    // mean_sum: reduction over rows, independent across columns (j_col).
    {
        Var jo("jo_mean"), ji("ji_mean");
        mean_sum
            .compute_root()
            // Split j_col so that we can parallelize outer and vectorize inner.
            .split(j_col, jo, ji, std::max(1, vec_width))
            .parallel(jo)
            .vectorize(ji);
    }

    // mean: simple pointwise op over columns.
    {
        Var jo("jo_mean2"), ji("ji_mean2");
        mean
            .compute_root()
            .split(j_col, jo, ji, std::max(1, vec_width))
            .parallel(jo)
            .vectorize(ji);
    }

    // var_sum: reduction over rows, independent across columns.
    {
        Var jo("jo_var"), ji("ji_var");
        var_sum
            .compute_root()
            .split(j_col, jo, ji, std::max(1, vec_width))
            .parallel(jo)
            .vectorize(ji);
    }

    // stddev: pointwise per column; cheap but parallelizable.
    {
        Var jo("jo_std"), ji("ji_std");
        stddev
            .compute_root()
            .split(j_col, jo, ji, std::max(1, vec_width))
            .parallel(jo)
            .vectorize(ji);
    }

    // normalized(sample, col):
    //   outer loop over columns (col) -> parallelized,
    //   inner loop over samples (sample) -> vectorized (contiguous).
    normalized
        .compute_root()
        .parallel(col)
        .vectorize(sample, std::max(1, vec_width));

    // corr_base(q, p):
    //   outer loop over rows of correlation (p) -> parallelized,
    //   inner loop over columns (q)             -> vectorized.
    //
    // The reduction domain r_k iterates over 'sample'; since 'sample'
    // is the contiguous dimension of 'normalized', this gives good
    // cache behavior.
    corr_base
        .compute_root()
        .parallel(p)
        .vectorize(q, std::max(1, vec_width));

    // Final corr(q, p) just applies the diagonal fix; it's a simple
    // pointwise transformation over the MxM matrix. We parallelize
    // across rows and vectorize across columns.
    corr
        .compute_root()
        .parallel(p)
        .vectorize(q, std::max(1, vec_width));

    // ---------------------------------------------------------------------

    // Bind parameters and input buffer.
    data_param.set(data);
    float_n_param.set(float_n);

    // Build a pipeline for the final correlation Func.
    Pipeline pipeline(corr);

    // JIT compile the pipeline.
    pipeline.compile_jit();

    // Time only the kernel execution (not initialization).
    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel: realize corr into corr_buf.
    pipeline.realize(corr_buf);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the result, similar to gemm.cpp.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int ii = 0; ii < m; ii++) {
            for (int jj = 0; jj < m; jj++) {
                // corr_buf(jj, ii) corresponds to corr[ii][jj] in C.
                std::cerr << corr_buf(jj, ii) << '\n';
            }
        }
    }

    // Print timing (seconds).
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
